/* A compact atlas keeps the hub bundle within the existing file and byte limits.
   Full image ZIPs use the local project collection; remote copies live in Drive. */
const photoGalleryState={selected:new Set(),filters:{},query:''};
const photoGalleryEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoGalleryLocal=()=>location.protocol.startsWith('http')&&location.pathname.includes('/Branding/Hub/');
const photoGalleryRows=()=>window.COOKT.photoLibrary.images;
const photoGalleryFile=r=>`../../../Photography/images/${encodeURIComponent(r.id)}.${r.extension}`;
const photoGalleryDrive=r=>`https://drive.google.com/file/d/${encodeURIComponent(r.driveId)}/view`;
const photoGalleryDownload=r=>`https://drive.google.com/uc?export=download&id=${encodeURIComponent(r.driveId)}`;
function photoGalleryOptions(key){return [...new Set(photoGalleryRows().map(x=>x[key]))].sort().map(x=>`<option value="${photoGalleryEsc(x)}">${photoGalleryEsc(x)}</option>`).join('');}
function renderHubPhotoGallery(){
 const lib=window.COOKT.photoLibrary;
 return `<section class="phlib"><div class="phlib-intro"><div><span class="eyebrow">Photography register / ${photoGalleryEsc(lib.version)}</span><h2>Every angle,<br>in one place.</h2><p>Food, lifestyle and lit packaging studies. Historical and concept imagery is labeled; five rejected or superseded directions stay in the private review register.</p></div><div class="phlib-total"><strong>${lib.images.length}</strong><span>images in the gallery</span></div></div>
 <div class="phlib-toolbar"><label>Search<input id="phlib-search" type="search" placeholder="Dish, scene, style, tag…"></label>${['type','style','plate','flavor','use','orientation'].map(k=>`<label>${k}<select data-phlib-filter="${k}"><option value="">All</option>${photoGalleryOptions(k)}</select></label>`).join('')}</div>
 <div class="phlib-actions"><span id="phlib-count"></span><button id="phlib-download" class="button" type="button">${photoGalleryLocal()?'Download selected ZIP':'Get selected file links'} <span id="phlib-selected">0</span></button><a class="button" href="${photoGalleryEsc(lib.driveFolderUrl)}" target="_blank" rel="noopener">Open Drive collection ↗</a></div>
 <div id="phlib-results"></div>
 <section class="phlib-missing"><span class="eyebrow">Shot gaps</span><h2>Still to make</h2><div class="phlib-gap-grid">${lib.missingShots.map(x=>`<article><small>${photoGalleryEsc(x.group)} / ${photoGalleryEsc(x.priority)}</small><h3>${photoGalleryEsc(x.title)}</h3><p>${photoGalleryEsc(x.detail)}</p></article>`).join('')}</div></section></section>`;
}
function photoGalleryMatches(r){const s=photoGalleryState;for(const [k,v] of Object.entries(s.filters))if(v&&r[k]!==v)return false;const q=s.query.toLowerCase();return !q||[r.title,r.type,r.style,r.plate,r.flavor,r.use,r.group,...(r.tags||[])].join(' ').toLowerCase().includes(q);}
function photoGalleryCard(r,index){const rows=Math.ceil(photoGalleryRows().length/8),col=index%8,row=Math.floor(index/8);const xp=col/7*100,yp=rows===1?0:row/(rows-1)*100;const checked=photoGalleryState.selected.has(r.id);
 return `<article class="phlib-card"><div class="phlib-image" role="img" aria-label="${photoGalleryEsc(r.title)}" style="background-position:${xp}% ${yp}%;background-size:800% ${rows*100}%"><label><input type="checkbox" data-phlib-select="${photoGalleryEsc(r.id)}" ${checked?'checked':''}> Select</label></div><div class="phlib-card-copy"><h4>${photoGalleryEsc(r.title)}</h4><p>${photoGalleryEsc(r.flavor)} / ${photoGalleryEsc(r.style)} / ${photoGalleryEsc(r.orientation)}<br>${photoGalleryEsc(r.plate)} / ${photoGalleryEsc(r.use)}</p><small>${photoGalleryEsc(r.status)}</small><div><a href="${photoGalleryEsc(photoGalleryLocal()?photoGalleryFile(r):photoGalleryDownload(r))}" ${photoGalleryLocal()?'download':''} target="_blank" rel="noopener">Download image ↓</a><a href="${photoGalleryEsc(photoGalleryDrive(r))}" target="_blank" rel="noopener">Drive ↗</a></div></div></article>`;
}
function drawHubPhotoGallery(){const container=document.querySelector('#phlib-results');if(!container)return;const rows=photoGalleryRows().map((r,index)=>({r,index})).filter(x=>photoGalleryMatches(x.r));const groups=new Map();for(const x of rows){if(!groups.has(x.r.group))groups.set(x.r.group,[]);groups.get(x.r.group).push(x);}container.innerHTML=groups.size?[...groups].sort(([a],[b])=>a.localeCompare(b)).map(([group,items])=>`<section class="phlib-group"><div class="phlib-group-head"><h3>${photoGalleryEsc(group)}</h3><span>${items.length} images</span></div><div class="phlib-grid">${items.sort((a,b)=>[a.r.flavor,a.r.style,a.r.title].join('|').localeCompare([b.r.flavor,b.r.style,b.r.title].join('|'))).map(x=>photoGalleryCard(x.r,x.index)).join('')}</div></section>`).join(''):'<p class="phlib-empty">No images match these filters.</p>';
 document.querySelector('#phlib-count').textContent=`${rows.length} shown`;
 document.querySelector('#phlib-selected').textContent=photoGalleryState.selected.size;
}
function photoGallerySave(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const photoCrcTable=Array.from({length:256},(_,i)=>{let c=i;for(let n=0;n<8;n++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
function photoCrc(bytes){let c=0xffffffff;for(const x of bytes)c=photoCrcTable[(c^x)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
const photo16=n=>new Uint8Array([n&255,(n>>>8)&255]);
const photo32=n=>new Uint8Array([n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]);
function photoConcat(parts){let len=0;for(const p of parts)len+=p.length;const out=new Uint8Array(len);let pos=0;for(const p of parts){out.set(p,pos);pos+=p.length;}return out;}
function photoZip(files){const local=[],central=[];let offset=0;const enc=new TextEncoder();for(const {name,bytes} of files){const filename=enc.encode(name),crc=photoCrc(bytes);const lh=photoConcat([photo32(0x04034b50),photo16(20),photo16(0),photo16(0),photo16(0),photo16(0),photo32(crc),photo32(bytes.length),photo32(bytes.length),photo16(filename.length),photo16(0),filename,bytes]);const cd=photoConcat([photo32(0x02014b50),photo16(20),photo16(20),photo16(0),photo16(0),photo16(0),photo16(0),photo32(crc),photo32(bytes.length),photo32(bytes.length),photo16(filename.length),photo16(0),photo16(0),photo16(0),photo16(0),photo32(0),photo32(offset),filename]);local.push(lh);central.push(cd);offset+=lh.length;}const directory=photoConcat(central),end=photoConcat([photo32(0x06054b50),photo16(0),photo16(0),photo16(files.length),photo16(files.length),photo32(directory.length),photo32(offset),photo16(0)]);return new Blob([...local,directory,end],{type:'application/zip'});}
async function photoGalleryDownloadSelected(){const selected=photoGalleryRows().filter(x=>photoGalleryState.selected.has(x.id));if(!selected.length){document.querySelector('#phlib-download').focus();return;}const manifest={collection:'COOKT Photography',version:window.COOKT.photoLibrary.version,images:selected.map(r=>({id:r.id,title:r.title,driveUrl:photoGalleryDrive(r),downloadUrl:photoGalleryDownload(r)}))};if(!photoGalleryLocal()){photoGallerySave('COOKT-photo-selection.json',new Blob([JSON.stringify(manifest,null,2)],{type:'application/json'}));return;}
 const button=document.querySelector('#phlib-download');button.disabled=true;button.textContent=`Preparing ${selected.length} images…`;try{const files=[];for(const r of selected){const response=await fetch(photoGalleryFile(r));if(!response.ok)throw new Error(r.id);files.push({name:r.id+'.'+r.extension,bytes:new Uint8Array(await response.arrayBuffer())});}files.push({name:'selection.json',bytes:new TextEncoder().encode(JSON.stringify(manifest,null,2))});photoGallerySave(`COOKT-photo-selection-${selected.length}.zip`,photoZip(files));}catch{photoGallerySave('COOKT-photo-selection.json',new Blob([JSON.stringify(manifest,null,2)],{type:'application/json'}));}finally{button.disabled=false;button.innerHTML=`Download selected ZIP <span id="phlib-selected">${photoGalleryState.selected.size}</span>`;}}
function bindHubPhotoGallery(){if(!document.querySelector('.phlib'))return;drawHubPhotoGallery();document.querySelector('#phlib-search').oninput=e=>{photoGalleryState.query=e.target.value;drawHubPhotoGallery();};document.querySelectorAll('[data-phlib-filter]').forEach(el=>el.onchange=e=>{photoGalleryState.filters[e.target.dataset.phlibFilter]=e.target.value;drawHubPhotoGallery();});document.querySelector('#phlib-results').onchange=e=>{const id=e.target.dataset.phlibSelect;if(!id)return;e.target.checked?photoGalleryState.selected.add(id):photoGalleryState.selected.delete(id);document.querySelector('#phlib-selected').textContent=photoGalleryState.selected.size;};document.querySelector('#phlib-download').onclick=photoGalleryDownloadSelected;}
